def group_test(name):
 if 'Outreach' in name or 'StepRecipients' in name:return 'outreach'
 if 'Comments' in name or 'Review.' in name or 'account-invitations' in name:return 'review'
 if 'Survey' in name:return 'survey-preservation'
 if 'Social' in name:return 'social'
 if 'BrandKit' in name or 'FontPicker' in name:return 'brand'
 if 'AssetDetails' in name or 'ContentStudio' in name:return 'asset-library'
 if any(k in name for k in ['Apps','StockImages','ImageAi','ImageAltText','LinkChecker','VideoDesign','VideoUrl']):return 'content-tools'
 if any(k in name for k in ['Image','image-editor','image-revisions','QuickCrop']):return 'image-editing'
 return 'authoring'
